	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/streams", wrapper.ListStreams)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/streams", wrapper.CreateStream)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/streams/{id}", wrapper.DeleteStream)
